/// Schema bytes 的摘要索引访问（小写 64 位十六进制字节 SHA-256）。
#[rustfmt::skip]
pub fn schema_by_digest(sha256_hex: &str) -> Option<&'static SchemaEntry> {
    SCHEMAS.iter().find(|e| e.sha256_hex == sha256_hex)
}

/// 按上游注册表 contract id 访问。
#[rustfmt::skip]
pub fn schema_by_id(id: &str) -> Option<&'static SchemaEntry> {
    SCHEMAS.iter().find(|e| e.id == id)
}
